1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"fmt"
8		"hash/crc32"
9		"io"
10		"os"
11	)
12	
13	// On-disk write-ahead log.
14	//
15	// Every successful Put/Delete (and every successfully acquired Snapshot) is
16	// appended as one framed record and forced to stable storage before the call
17	// reports success, so reopening a directory always replays a prefix of
18	// complete records (never a half-written value) and the cumulative snapshot
19	// count is never reset.
20	//
21	// Frame layout, little-endian:
22	//
23	//	magic    uint32   recordMagic
24	//	op       byte     opPut, opDelete, opMeta, opPutSeq or opDeleteSeq
25	//	keyLen   uint32
26	//	valLen   uint32
27	//	key      [keyLen]byte
28	//	value    [valLen]byte (absent for plain deletes)
29	//	crc      uint32   IEEE CRC-32 of all preceding frame bytes
30	//
31	// An opMeta record carries no key and an 8-byte little-endian value holding
32	// the cumulative number of snapshots handed out so far.
33	//
34	// opPut/opDelete are the original records and carry no sequence number; they
35	// remain readable forever so a directory written by an older version reopens
36	// unchanged. Records written by this version use the Seq variants instead:
37	// the value area is an 8-byte little-endian commit sequence number (unique
38	// and increasing per key) followed, for puts, by the actual value
39	// (valLen = 8 + len(value)). Sequence numbers let a pinning compaction merge
40	// versions from several eras into one history while keeping their order.
41	const (
42		walName = "wal.log"
43		// compactTmpName holds a freshly built log during compaction; it is
44		// atomically renamed over wal.log and never observed directly. A file by
45		// this name left behind by a crash mid-compaction is stale and removed on
46		// the next open.
47		compactTmpName = "wal.log.compact"
48	
49		recordMagic uint32 = 0x534e4150 // "SNAP"
50		opPut       byte   = 1
51		opDelete    byte   = 2
52		opMeta      byte   = 3
53		opPutSeq    byte   = 4
54		opDeleteSeq byte   = 5
55	
56		frameHeaderSize = 4 + 1 + 4 + 4
57		crcSize         = 4
58		metaValueSize   = 8
59		seqSize         = 8
60		maxRecord       = 1 << 30 // sanity bound on key and value lengths
61	)
62	
63	type walWriter struct {
64		f *os.File
65		w *bufio.Writer
66	}
67	
68	func openWALWriter(dir string, replaySize int64) (*walWriter, error) {
69		f, err := os.OpenFile(dir+string(os.PathSeparator)+walName, os.O_RDWR|os.O_CREATE, 0o600)
70		if err != nil {
71			return nil, err
72		}
73		// Drop any torn tail that replay could not consume. A negative replaySize
74		// means the file is already exactly what should be on disk (e.g. a log
75		// just installed by compaction) and must not be truncated.
76		if replaySize >= 0 {
77			if err := f.Truncate(replaySize); err != nil {
78				f.Close()
79				return nil, err
80			}
81		}
82		if _, err := f.Seek(0, io.SeekEnd); err != nil {
83			f.Close()
84			return nil, err
85		}
86		return &walWriter{f: f, w: bufio.NewWriter(f)}, nil
87	}
88	
89	func (l *walWriter) writeFrame(op byte, key string, value []byte) error {
90		if err := l.encodeFrame(op, key, value); err != nil {
91			return err
92		}
93		if err := l.w.Flush(); err != nil {
94			return err
95		}
96		return l.f.Sync()
97	}
98	
99	// encodeFrame buffers one framed record. Used for ordinary appends (followed
100	// by a flush and sync) and while building a replacement log from scratch.
101	func (l *walWriter) encodeFrame(op byte, key string, value []byte) error {
102		hdr := make([]byte, frameHeaderSize)
103		binary.LittleEndian.PutUint32(hdr[0:4], recordMagic)
104		hdr[4] = op
105		binary.LittleEndian.PutUint32(hdr[5:9], uint32(len(key)))
106		binary.LittleEndian.PutUint32(hdr[9:13], uint32(len(value)))
107	
108		h := crc32.NewIEEE()
109		h.Write(hdr)
110		if _, err := l.w.Write(hdr); err != nil {
111			return err
112		}
113		if _, err := io.WriteString(l.w, key); err != nil {
114			return err
115		}
116		h.Write([]byte(key))
117		if len(value) > 0 {
118			if _, err := l.w.Write(value); err != nil {
119				return err
120			}
121			h.Write(value)
122		}
123		var crcb [crcSize]byte
124		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
125		_, err := l.w.Write(crcb[:])
126		return err
127	}
128	
129	// encodeFrameSeq buffers a Seq record: seq's 8 bytes followed by value in
130	// the value area.
131	func (l *walWriter) encodeFrameSeq(op byte, key string, seq uint64, value []byte) error {
132		hdr := make([]byte, frameHeaderSize)
133		binary.LittleEndian.PutUint32(hdr[0:4], recordMagic)
134		hdr[4] = op
135		binary.LittleEndian.PutUint32(hdr[5:9], uint32(len(key)))
136		binary.LittleEndian.PutUint32(hdr[9:13], seqSize+uint32(len(value)))
137	
138		h := crc32.NewIEEE()
139		h.Write(hdr)
140		if _, err := l.w.Write(hdr); err != nil {
141			return err
142		}
143		if _, err := io.WriteString(l.w, key); err != nil {
144			return err
145		}
146		h.Write([]byte(key))
147		var seqb [seqSize]byte
148		binary.LittleEndian.PutUint64(seqb[:], seq)
149		if _, err := l.w.Write(seqb[:]); err != nil {
150			return err
151		}
152		h.Write(seqb[:])
153		if len(value) > 0 {
154			if _, err := l.w.Write(value); err != nil {
155				return err
156			}
157			h.Write(value)
158		}
159		var crcb [crcSize]byte
160		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
161		_, err := l.w.Write(crcb[:])
162		return err
163	}
164	
165	// appendPut writes and durably commits one value record tagged with seq.
166	func (l *walWriter) appendPut(key string, value []byte, seq uint64) error {
167		if len(key) > maxRecord || seqSize+len(value) > maxRecord {
168			return fmt.Errorf("snapshot: record too large")
169		}
170		if err := l.encodeFrameSeq(opPutSeq, key, seq, value); err != nil {
171			return err
172		}
173		if err := l.w.Flush(); err != nil {
174			return err
175		}
176		return l.f.Sync()
177	}
178	
179	// appendDelete writes and durably commits one tombstone tagged with seq.
180	func (l *walWriter) appendDelete(key string, seq uint64) error {
181		if len(key) > maxRecord {
182			return fmt.Errorf("snapshot: record too large")
183		}
184		if err := l.encodeFrameSeq(opDeleteSeq, key, seq, nil); err != nil {
185			return err
186		}
187		if err := l.w.Flush(); err != nil {
188			return err
189		}
190		return l.f.Sync()
191	}
192	
193	// appendMeta durably records the cumulative snapshot count.
194	func (l *walWriter) appendMeta(snapshotCount uint64) error {
195		var v [metaValueSize]byte
196		binary.LittleEndian.PutUint64(v[:], snapshotCount)
197		return l.writeFrame(opMeta, "", v[:])
198	}
199	
200	func (l *walWriter) close() error { return l.f.Close() }
201	
202	// syncDirectory forces a directory entry change (such as a rename) to stable
203	// storage.
204	func syncDirectory(dir string) error {
205		d, err := os.Open(dir)
206		if err != nil {
207			return err
208		}
209		defer d.Close()
210		return d.Sync()
211	}
212	
213	// removeStaleCompact deletes a replacement log left behind by a compaction
214	// that crashed before its atomic rename. Its absence is not an error.
215	func removeStaleCompact(dir string) error {
216		err := os.Remove(dir + string(os.PathSeparator) + compactTmpName)
217		if err != nil && !errors.Is(err, os.ErrNotExist) {
218			return err
219		}
220		return nil
221	}
222	
223	// compactWAL atomically replaces the write-ahead log with one containing only
224	// the given live values, followed by one meta record with snapshotCount. It
225	// builds the complete replacement in compactTmpName, forces it to stable
226	// storage, then atomically renames it over wal.log and forces the directory.
227	// A crash at any point therefore leaves either the old log or the complete
228	// new log: never a truncated or half-written file. On success it returns a
229	// fresh writer positioned at the end of the new log. If the directory sync
230	// fails the rename has still happened, so a non-nil writer is returned
231	// together with the error: the caller must adopt it rather than keep writing
232	// to the old, now-unlinked file.
233	func compactWAL(dir string, histories []keyHistory, snapshotCount uint64) (*walWriter, error) {
234		if err := removeStaleCompact(dir); err != nil {
235			return nil, err
236		}
237	
238		path := dir + string(os.PathSeparator)
239		tmp, err := os.OpenFile(path+compactTmpName, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
240		if err != nil {
241			return nil, err
242		}
243		l := &walWriter{f: tmp, w: bufio.NewWriter(tmp)}
244		for i := range histories {
245			// Each key's retained versions are oldest-to-newest; replay prepends
246			// them in this order, so the last one becomes the head and every
247			// older one remains reachable down its chain. Frames are only
248			// buffered here; one flush plus one sync below commits the whole
249			// replacement atomically.
250			for _, ver := range histories[i].versions {
251				if ver.present {
252					if err := l.encodeFrameSeq(opPutSeq, histories[i].key, ver.seq, ver.value); err != nil {
253						tmp.Close()
254						os.Remove(path + compactTmpName)
255						return nil, err
256					}
257				} else {
258					if err := l.encodeFrameSeq(opDeleteSeq, histories[i].key, ver.seq, nil); err != nil {
259						tmp.Close()
260						os.Remove(path + compactTmpName)
261						return nil, err
262					}
263				}
264			}
265		}
266		// A zero count needs no record: replay of an absent meta yields 0. This
267		// keeps a trivially empty log empty rather than growing it.
268		if snapshotCount > 0 {
269			var v [metaValueSize]byte
270			binary.LittleEndian.PutUint64(v[:], snapshotCount)
271			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
272				tmp.Close()
273				os.Remove(path + compactTmpName)
274				return nil, err
275			}
276		}
277		if err := l.w.Flush(); err != nil {
278			tmp.Close()
279			os.Remove(path + compactTmpName)
280			return nil, err
281		}
282		if err := tmp.Sync(); err != nil {
283			tmp.Close()
284			os.Remove(path + compactTmpName)
285			return nil, err
286		}
287		if err := tmp.Close(); err != nil {
288			os.Remove(path + compactTmpName)
289			return nil, err
290		}
291	
292		if err := os.Rename(path+compactTmpName, path+walName); err != nil {
293			os.Remove(path + compactTmpName)
294			return nil, err
295		}
296		// Make the rename durable; otherwise a crash could expose the old log
297		// even though the new one was fully written. The rename itself has
298		// already landed either way, so open and return the new writer so the
299		// caller adopts the now-linked file despite reporting the error.
300		syncErr := syncDirectory(dir)
301		next, openErr := openWALWriter(dir, -1)
302		if openErr != nil {
303			// Join collapses to whichever error is set (or both, if both).
304			return nil, errors.Join(syncErr, openErr)
305		}
306		return next, syncErr
307	}
308	
309	// nodeVer is one retained version of a key.
310	type nodeVer struct {
311		seq     uint64
312		present bool // false marks a delete
313		value   []byte
314	}
315	
316	// keyHistory is the retained oldest-to-newest version chain for one key in a
317	// compacted log.
318	type keyHistory struct {
319		key      string
320		versions []nodeVer
321	}
322	
323	// replayWAL applies every complete, intact record in commit order. kv
324	// records go to fn with their commit sequence (0 for legacy records that
325	// predate sequence numbers); meta records update snapshotCount. It returns
326	// the number of bytes occupied by the valid prefix; anything after it is a
327	// torn or corrupt tail discarded on the next open.
328	func replayWAL(dir string, fn func(op byte, key string, value []byte, seq uint64)) (int64, uint64, error) {
329		f, err := os.Open(dir + string(os.PathSeparator) + walName)
330		if err != nil {
331			if errors.Is(err, os.ErrNotExist) {
332				return 0, 0, nil
333			}
334			return 0, 0, err
335		}
336		defer f.Close()
337	
338		r := bufio.NewReader(f)
339		var offset int64
340		var snapshotCount uint64
341		hdr := make([]byte, frameHeaderSize)
342	
343		for {
344			start := offset
345			if _, err := io.ReadFull(r, hdr); err != nil {
346				if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
347					return start, snapshotCount, nil // absent/torn tail: valid prefix ends here
348				}
349				return 0, 0, err
350			}
351			offset += frameHeaderSize
352	
353			magic := binary.LittleEndian.Uint32(hdr[0:4])
354			op := hdr[4]
355			keyLen := binary.LittleEndian.Uint32(hdr[5:9])
356			valLen := binary.LittleEndian.Uint32(hdr[9:13])
357			if magic != recordMagic ||
358				(op != opPut && op != opDelete && op != opMeta &&
359					op != opPutSeq && op != opDeleteSeq) ||
360				keyLen > maxRecord || valLen > maxRecord ||
361				(op == opDelete && valLen != 0) ||
362				(op == opPutSeq && valLen < seqSize) ||
363				(op == opDeleteSeq && valLen != seqSize) ||
364				(op == opMeta && (keyLen != 0 || valLen != metaValueSize)) {
365				return start, snapshotCount, nil // corrupt frame: valid prefix ends here
366			}
367	
368			body := make([]byte, int(keyLen)+int(valLen))
369			if _, err := io.ReadFull(r, body); err != nil {
370				return start, snapshotCount, nil
371			}
372			offset += int64(len(body))
373	
374			var crcb [crcSize]byte
375			if _, err := io.ReadFull(r, crcb[:]); err != nil {
376				return start, snapshotCount, nil
377			}
378			offset += crcSize
379	
380			h := crc32.NewIEEE()
381			h.Write(hdr)
382			h.Write(body)
383			if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
384				return start, snapshotCount, nil
385			}
386	
387			switch op {
388			case opPut:
389				key := string(body[:keyLen])
390				fn(opPut, key, body[keyLen:], 0)
391			case opDelete:
392				fn(opDelete, string(body[:keyLen]), nil, 0)
393			case opPutSeq:
394				key := string(body[:keyLen])
395				seq := binary.LittleEndian.Uint64(body[keyLen : keyLen+seqSize])
396				fn(opPutSeq, key, body[keyLen+seqSize:], seq)
397			case opDeleteSeq:
398				key := string(body[:keyLen])
399				seq := binary.LittleEndian.Uint64(body[keyLen : keyLen+seqSize])
400				fn(opDeleteSeq, key, nil, seq)
401			case opMeta:
402				snapshotCount = binary.LittleEndian.Uint64(body)
403			}
404		}
405	}
