1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"io/fs"
10		"os"
11		"sort"
12		"sync"
13		"sync/atomic"
14	)
15	
16	// node is one immutable version in a key's history. Versions form a linked
17	// list from newest to oldest; a snapshot pins the head current when it was
18	// acquired, so overwritten and deleted values stay readable through every
19	// view that references them. seq is the version's commit number, unique and
20	// strictly increasing along each key's chain; it orders versions across the
21	// independent chains that meet again during a pinning compaction.
22	type node struct {
23		value   []byte
24		present bool   // false marks a delete; a present nil/empty value is still a hit
25		seq     uint64 // commit order, 1-based
26		older   *node
27	}
28	
29	// view is an immutable map of keys to their newest version. Updates produce a
30	// fresh map; the current view and every snapshot simply point at one. Views
31	// are never mutated after publication, so reading them needs no lock. The
32	// maps share version chains with their successor views.
33	type view map[string]*node
34	
35	// Store is an open key-value store backed by a directory on disk.
36	type Store struct {
37		mu sync.Mutex // serializes writers and guards the fields below
38	
39		dir       string
40		wal       *walWriter
41		current   atomic.Pointer[view] // latest committed view; lock-free for readers
42		snapshots atomic.Uint64        // cumulative number of snapshots handed out
43		nextSeq   uint64               // highest commit sequence handed out; guarded by mu
44	
45		// Open cursors pin their fixed view's versions against compaction. The
46		// set is read by Compact (which holds mu) and mutated at cursor
47		// open/close, using cursorMu; reads never take either lock.
48		cursorMu sync.Mutex
49		cursors  map[*Cursor]struct{}
50	
51		closed atomic.Bool
52	}
53	
54	// Snapshot is a stable read-only view of a store captured at one instant. It
55	// owns no store resources of its own and stays usable after the store has
56	// been closed; a cursor opened from it does register with the store while it
57	// pins versions.
58	type Snapshot struct {
59		v     atomic.Pointer[view] // nil once the snapshot is closed
60		store *Store               // back-reference for cursor pin accounting
61	}
62	
63	// Open opens or creates a persistent store in dir. A path that names a
64	// regular file rather than a directory returns an error wrapping
65	// fs.ErrInvalid.
66	func Open(dir string) (*Store, error) {
67		info, err := os.Stat(dir)
68		if err == nil {
69			if !info.IsDir() {
70				return nil, errNotDir
71			}
72		} else {
73			if !errors.Is(err, fs.ErrNotExist) {
74				return nil, err
75			}
76			if err := os.MkdirAll(dir, 0o700); err != nil {
77				return nil, err
78			}
79		}
80	
81		// A replacement log from a compaction killed before its rename can never
82		// be complete state of record; the old wal.log is. Drop the stale file.
83		if err := removeStaleCompact(dir); err != nil {
84			return nil, err
85		}
86	
87		latest := make(view)
88		var replaySeq uint64
89		validSize, snapshotCount, err := replayWAL(dir, func(op byte, key string, value []byte, seq uint64) {
90			// Legacy records (written before sequence numbers existed) carry no
91			// seq; replay order is commit order, so number them sequentially.
92			if seq == 0 {
93				replaySeq++
94				seq = replaySeq
95			} else if seq > replaySeq {
96				replaySeq = seq
97			}
98			switch op {
99			case opPut, opPutSeq:
100				latest[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: latest[key]}
101			case opDelete, opDeleteSeq:
102				latest[key] = &node{present: false, seq: seq, older: latest[key]}
103			}
104		})
105		if err != nil {
106			return nil, err
107		}
108	
109		wal, err := openWALWriter(dir, validSize)
110		if err != nil {
111			return nil, err
112		}
113	
114		s := &Store{dir: dir, wal: wal, cursors: make(map[*Cursor]struct{}), nextSeq: replaySeq}
115		s.snapshots.Store(snapshotCount)
116		s.current.Store(&latest)
117		return s, nil
118	}
119	
120	// Put stores value under key. An empty key returns an error wrapping
121	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
122	// key reports a hit. The store does not keep a reference to value.
123	func (s *Store) Put(key string, value []byte) error {
124		s.mu.Lock()
125		defer s.mu.Unlock()
126		if s.closed.Load() {
127			return errStoreClosed
128		}
129		if key == "" {
130			return errEmptyKey
131		}
132		seq := s.nextSeq + 1
133		if err := s.wal.appendPut(key, value, seq); err != nil {
134			return err
135		}
136		s.nextSeq = seq
137		next := s.deriveView()
138		next[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: (*s.current.Load())[key]}
139		s.current.Store(&next)
140		return nil
141	}
142	
143	// Get returns the latest committed value for key. Empty keys, keys never
144	// written and deleted keys are all misses: ok is false and err is nil. The
145	// returned bytes are owned by the caller.
146	func (s *Store) Get(key string) ([]byte, bool, error) {
147		if s.closed.Load() {
148			return nil, false, errStoreClosed
149		}
150		if key == "" {
151			return nil, false, nil
152		}
153		val, ok := lookup(*s.current.Load(), key)
154		return val, ok, nil
155	}
156	
157	// Delete removes key. Deleting an empty key returns an error wrapping
158	// fs.ErrInvalid; deleting a key that was never written or is already deleted
159	// is not an error and commits nothing.
160	func (s *Store) Delete(key string) error {
161		s.mu.Lock()
162		defer s.mu.Unlock()
163		if s.closed.Load() {
164			return errStoreClosed
165		}
166		if key == "" {
167			return errEmptyKey
168		}
169		cur := *s.current.Load()
170		if n := cur[key]; n == nil || !n.present {
171			return nil // nothing live to delete: idempotent no-op
172		}
173		seq := s.nextSeq + 1
174		if err := s.wal.appendDelete(key, seq); err != nil {
175			return err
176		}
177		s.nextSeq = seq
178		next := s.deriveView()
179		next[key] = &node{present: false, seq: seq, older: cur[key]}
180		s.current.Store(&next)
181		return nil
182	}
183	
184	// deriveView returns a shallow, mutable copy of the current view. Callers
185	// must hold s.mu and publish the result through s.current before unlocking.
186	func (s *Store) deriveView() view {
187		cur := *s.current.Load()
188		next := make(view, len(cur)+1)
189		for k, v := range cur {
190			next[k] = v
191		}
192		return next
193	}
194	
195	// Compact reclaims history: values that were overwritten or deleted and are
196	// not needed by any open snapshot or cursor are dropped from memory and the
197	// write-ahead log is atomically rewritten, so the directory occupies less
198	// space than before whenever reclaimable history existed.
199	//
200	// Every open snapshot keeps its exact fixed view: its values are untouched
201	// and reads before and after compaction return byte-identical results. Every
202	// open cursor likewise keeps paging through its exact fixed sequence, and
203	// the one version per key its view shows stays in the rewritten log until
204	// the cursor closes; the compaction after that drops it and shrinks the
205	// directory further. A process killed at any point during compaction reopens
206	// in a complete commit state, with every successful write, deletion and the
207	// cumulative snapshot count intact; no intermediate file requires a second
208	// compaction to repair.
209	//
210	// Compact takes no arguments, may be called at any time and serializes with
211	// writes, deletes, snapshots, cursor opens, closing and other compactions;
212	// concurrent or repeated calls queue and all return nil. Compacting a closed
213	// store returns an error wrapping fs.ErrClosed.
214	func (s *Store) Compact() error {
215		s.mu.Lock()
216		defer s.mu.Unlock()
217		if s.closed.Load() {
218			return errStoreClosed
219		}
220	
221		cur := *s.current.Load()
222	
223		// Pinned versions, keyed by commit sequence (globally unique). The
224		// current head of every live key in the latest view is retained; each
225		// open cursor additionally pins the single head version its fixed view
226		// shows for every present key in its range. A deleted key's tombstone is
227		// retained only when a cursor still reads an older value under it, so
228		// replay links that value as the tombstone's predecessor; otherwise the
229		// key is dropped from the rewritten log altogether, as before.
230		pinned := make(map[uint64]*node)
231		keySeqs := make(map[string][]uint64)
232		cursorPins := make(map[string]bool)
233		pin := func(k string, n *node) {
234			if n == nil {
235				return
236			}
237			if _, ok := pinned[n.seq]; !ok {
238				pinned[n.seq] = n
239				keySeqs[k] = append(keySeqs[k], n.seq)
240			}
241		}
242		for _, c := range s.openCursors() {
243			v := *c.v
244			for _, k := range c.keys {
245				cursorPins[k] = true
246				pin(k, v[k]) // exactly the version this cursor pages out
247			}
248		}
249		for k, n := range cur {
250			if n.present || cursorPins[k] {
251				pin(k, n) // live head, or a tombstone shielding a pinned value
252			}
253		}
254	
255		// Emit one oldest-to-newest history per key so replay links the retained
256		// versions into the correct chains. A key deleted with no cursor reading
257		// an older value is absent from keySeqs altogether and drops out of both
258		// the new view and the rewritten log, exactly as in the baseline.
259		keys := make([]string, 0, len(keySeqs))
260		for k := range keySeqs {
261			keys = append(keys, k)
262		}
263		sort.Strings(keys)
264		histories := make([]keyHistory, 0, len(keys))
265		fresh := make(view, len(cur))
266		for _, k := range keys {
267			seqs := keySeqs[k]
268			sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
269			h := keyHistory{key: k, versions: make([]nodeVer, 0, len(seqs))}
270			for _, seq := range seqs {
271				n := pinned[seq]
272				h.versions = append(h.versions, nodeVer{
273					seq: seq, present: n.present, value: n.value,
274				})
275			}
276			histories = append(histories, h)
277	
278			// The new current view gets single-node heads: history nobody pins
279			// becomes unreachable from memory here, while open snapshots and
280			// cursors keep their own views and nodes alive.
281			head := pinned[seqs[len(seqs)-1]]
282			if head.present {
283				fresh[k] = &node{value: head.value, present: true, seq: head.seq}
284			}
285		}
286	
287		// The rewrite is crash-atomic: on return either the old log or the fully
288		// built new log is wal.log. Swapping the writer under s.mu means a
289		// concurrent writer cannot straddle the two files. A non-nil nextWAL
290		// means the rename landed even if the final directory sync reported an
291		// error; adopt it (the old file is unlinked) and publish the matching
292		// view, then surface the sync error.
293		nextWAL, compactErr := compactWAL(s.dir, histories, s.snapshots.Load())
294		if nextWAL == nil {
295			return compactErr
296		}
297		oldWAL := s.wal
298		s.wal = nextWAL
299		s.current.Store(&fresh)
300		if err := oldWAL.close(); err != nil && compactErr == nil {
301			return err
302		}
303		return compactErr
304	}
305	
306	// openCursors snapshots the set of currently open cursors. Cursor views and
307	// bounds are immutable after opening, so reading their fields here needs no
308	// per-cursor lock.
309	func (s *Store) openCursors() []*Cursor {
310		s.cursorMu.Lock()
311		defer s.cursorMu.Unlock()
312		cs := make([]*Cursor, 0, len(s.cursors))
313		for c := range s.cursors {
314			cs = append(cs, c)
315		}
316		return cs
317	}
318	
319	// Snapshot acquires a stable view. It never observes writes committed after
320	// it returns, and keeps serving that view regardless of later writes,
321	// deletes or Store.Close, until the Snapshot itself is closed.
322	func (s *Store) Snapshot() (*Snapshot, error) {
323		s.mu.Lock()
324		defer s.mu.Unlock()
325		if s.closed.Load() {
326			return nil, errStoreClosed
327		}
328		count := s.snapshots.Add(1)
329		if err := s.wal.appendMeta(count); err != nil {
330			s.snapshots.Add(^uint64(0))
331			return nil, err
332		}
333		snap := &Snapshot{store: s}
334		snap.v.Store(s.current.Load())
335		return snap, nil
336	}
337	
338	// Get reads key from the snapshot's fixed view. Old values overwritten or
339	// deleted afterwards are still readable; keys created afterwards, empty
340	// keys and keys absent or deleted when the snapshot was taken are misses. A
341	// read from a closed snapshot is also a plain miss, never an error. The
342	// returned bytes are owned by the caller.
343	func (s *Snapshot) Get(key string) ([]byte, bool) {
344		if key == "" {
345			return nil, false
346		}
347		v := s.v.Load()
348		if v == nil {
349			return nil, false // closed snapshot
350		}
351		n := (*v)[key]
352		if n == nil || !n.present {
353			return nil, false
354		}
355		return cloneBytes(n.value), true
356	}
357	
358	// Close releases the snapshot's fixed view. Closing more than once is a
359	// no-op returning nil.
360	func (s *Snapshot) Close() error {
361		s.v.Store(nil)
362		return nil
363	}
364	
365	// Close flushes and closes the store. Data already committed stays complete
366	// and readable after reopening the directory. Snapshots still open keep
367	// serving their fixed views until closed themselves; closing an already
368	// closed store is a no-op returning nil.
369	func (s *Store) Close() error {
370		s.mu.Lock()
371		if !s.closed.CompareAndSwap(false, true) {
372			s.mu.Unlock()
373			return nil
374		}
375		wal := s.wal
376		s.wal = nil
377		s.mu.Unlock()
378	
379		return wal.close()
380	}
381	
382	func lookup(v view, key string) ([]byte, bool) {
383		n := v[key]
384		if n == nil || !n.present {
385			return nil, false
386		}
387		return cloneBytes(n.value), true
388	}
389	
390	func cloneBytes(b []byte) []byte {
391		if b == nil {
392			return nil
393		}
394		c := make([]byte, len(b))
395		copy(c, b)
396		return c
397	}
