1	package snapshot
2	
3	import (
4		"sort"
5		"sync"
6	)
7	
8	// KVPair is one key/value pair returned by a scan. Value is owned by the
9	// caller after return, exactly as the bytes returned by Get.
10	type KVPair struct {
11		Key   string
12		Value []byte
13	}
14	
15	// Range selects the half-open key interval [Start, End), scanned in
16	// ascending byte order. An empty Start means the smallest key; an empty End
17	// means the largest key. Empty keys cannot be stored, so an empty bound is
18	// unambiguously "no bound". An interval whose Start is not strictly before
19	// End matches nothing.
20	type Range struct {
21		Start string
22		End   string
23	}
24	
25	// Scan returns up to limit present key/value pairs whose keys lie in the
26	// half-open interval r, in ascending byte order. A limit <= 0 returns every
27	// matching pair.
28	//
29	// A reversed interval (Start not before End) and a range matching no keys
30	// both return an empty slice and nil, never an error or partial data. Hit
31	// semantics match Get: keys written with empty values are included; empty
32	// keys, deleted keys and keys never written are not.
33	//
34	// The read hits the latest committed view directly in memory and is never
35	// held up by a write synchronizing to disk. Scanning a closed store returns
36	// an error wrapping fs.ErrClosed.
37	func (s *Store) Scan(r Range, limit int) ([]KVPair, error) {
38		if s.closed.Load() {
39			return nil, errStoreClosed
40		}
41		if !validInterval(r.Start, r.End) {
42			return []KVPair{}, nil
43		}
44		return scanView(*s.current.Load(), r.Start, r.End, limit), nil
45	}
46	
47	// ScanPrefix returns up to limit present pairs whose keys begin with prefix,
48	// in ascending byte order. An empty prefix matches every key. It is
49	// equivalent to Scan over the key interval the prefix occupies.
50	func (s *Store) ScanPrefix(prefix string, limit int) ([]KVPair, error) {
51		if s.closed.Load() {
52			return nil, errStoreClosed
53		}
54		return scanView(*s.current.Load(), prefix, prefixEnd(prefix), limit), nil
55	}
56	
57	// OpenCursor opens a cursor over the half-open interval r of the latest
58	// committed view. The cursor's view is fixed at open time: later writes,
59	// deletes, compactions, newly opened snapshots and Store.Close neither change
60	// nor invalidate what it pages through. The versions it references are kept
61	// out of compaction reclamation until it closes.
62	func (s *Store) OpenCursor(r Range) (*Cursor, error) {
63		s.mu.Lock()
64		defer s.mu.Unlock()
65		if s.closed.Load() {
66			return nil, errStoreClosed
67		}
68		if !validInterval(r.Start, r.End) {
69			return newEmptyCursor(), nil
70		}
71		return s.newCursor(s.current.Load(), r.Start, r.End), nil
72	}
73	
74	// OpenCursorPrefix opens a cursor over keys beginning with prefix.
75	func (s *Store) OpenCursorPrefix(prefix string) (*Cursor, error) {
76		s.mu.Lock()
77		defer s.mu.Unlock()
78		if s.closed.Load() {
79			return nil, errStoreClosed
80		}
81		return s.newCursor(s.current.Load(), prefix, prefixEnd(prefix)), nil
82	}
83	
84	// Scan is the Snapshot variant: it scans the snapshot's fixed view. A scan
85	// on a closed snapshot is an ordinary empty result, never an error, just as
86	// Get on a closed snapshot is a miss.
87	func (s *Snapshot) Scan(r Range, limit int) ([]KVPair, error) {
88		v := s.v.Load()
89		if v == nil || !validInterval(r.Start, r.End) {
90			return []KVPair{}, nil
91		}
92		return scanView(*v, r.Start, r.End, limit), nil
93	}
94	
95	// ScanPrefix scans the snapshot's fixed view for keys beginning with prefix.
96	func (s *Snapshot) ScanPrefix(prefix string, limit int) ([]KVPair, error) {
97		v := s.v.Load()
98		if v == nil {
99			return []KVPair{}, nil
100		}
101		return scanView(*v, prefix, prefixEnd(prefix), limit), nil
102	}
103	
104	// OpenCursor opens a cursor over the snapshot's fixed view. Versions the
105	// cursor pages through stay out of compaction reclamation until it closes.
106	// Opening a cursor does not count as taking a snapshot. On a closed snapshot
107	// it yields a cursor over an empty view, mirroring the miss-without-error
108	// semantics of every other closed-snapshot read.
109	func (s *Snapshot) OpenCursor(r Range) (*Cursor, error) {
110		v := s.v.Load()
111		if v == nil {
112			return newEmptyCursor(), nil
113		}
114		if !validInterval(r.Start, r.End) {
115			return newEmptyCursor(), nil
116		}
117		return s.openCursor(v, r.Start, r.End)
118	}
119	
120	// OpenCursorPrefix opens a cursor over the snapshot's fixed view restricted
121	// to keys beginning with prefix.
122	func (s *Snapshot) OpenCursorPrefix(prefix string) (*Cursor, error) {
123		v := s.v.Load()
124		if v == nil {
125			return newEmptyCursor(), nil
126		}
127		return s.openCursor(v, prefix, prefixEnd(prefix))
128	}
129	
130	func (s *Snapshot) openCursor(v *view, start, end string) (*Cursor, error) {
131		st := s.store
132		if st == nil || st.closed.Load() {
133			// The producing store is gone: no compaction can run anymore, so
134			// nothing has to pin. The cursor still serves its fixed in-memory
135			// view.
136			return newCursorPinned(nil, v, start, end), nil
137		}
138		// Register under the same lock Compact holds for its whole rewrite, so
139		// every compaction while this cursor is alive includes its versions.
140		st.mu.Lock()
141		defer st.mu.Unlock()
142		if st.closed.Load() {
143			return newCursorPinned(nil, v, start, end), nil
144		}
145		return st.newCursor(v, start, end), nil
146	}
147	
148	// Cursor pages in stable byte order over one fixed view. It is safe for
149	// concurrent use; paging never takes the store's write lock and is not
150	// blocked by writes syncing to disk.
151	type Cursor struct {
152		store *Store // pin accounting target; nil for an unpinned/empty cursor
153	
154		mu     sync.Mutex
155		v      *view // fixed at open; nil only on a fully inert handle
156		start  string
157		end    string
158		keys   []string // present keys in [start,end), sorted, fixed at open
159		closed bool
160	}
161	
162	// Page returns at most limit pairs of the cursor's fixed ordered sequence
163	// starting at offset off. The first call passes offset 0; each following call
164	// passes the previous offset plus the number of pairs it got back. Paged that
165	// way the calls reproduce the cursor's whole sequence byte-identically with
166	// neither duplicates nor gaps. An offset equal to the sequence length with a
167	// positive limit returns an empty page and nil, signalling the end.
168	//
169	// A non-positive limit, a negative offset, or an offset past the end of the
170	// sequence is an out-of-range or otherwise illegal continuation argument and
171	// returns an error wrapping fs.ErrInvalid. Paging a closed cursor is an empty
172	// result without error.
173	func (c *Cursor) Page(off, limit int) ([]KVPair, error) {
174		c.mu.Lock()
175		defer c.mu.Unlock()
176		if c.closed {
177			return []KVPair{}, nil
178		}
179		if limit <= 0 || off < 0 || off > len(c.keys) {
180			return nil, errCursorArgument
181		}
182		stop := off + limit
183		if stop > len(c.keys) || stop < off {
184			stop = len(c.keys) // clamp a large page; guard against int overflow
185		}
186		v := *c.v
187		out := make([]KVPair, 0, stop-off)
188		for _, k := range c.keys[off:stop] {
189			n := v[k]
190			if n == nil || !n.present {
191				continue // defensive: keys are fixed present-at-open, so unreachable
192			}
193			out = append(out, KVPair{Key: k, Value: cloneBytes(n.value)})
194		}
195		return out, nil
196	}
197	
198	// Close releases the cursor. Its versions become reclaimable by the next
199	// compaction. Close is idempotent, serializes with concurrent pages and
200	// other closes, and always returns nil; reads after Close are empty results
201	// without error.
202	func (c *Cursor) Close() error {
203		c.mu.Lock()
204		already := c.closed
205		c.closed = true
206		st := c.store
207		c.store = nil
208		c.mu.Unlock()
209	
210		if already || st == nil {
211			return nil
212		}
213		st.unregisterCursor(c)
214		return nil
215	}
216	
217	// ---- pin registry ----
218	
219	func (s *Store) registerCursor(c *Cursor) {
220		s.cursorMu.Lock()
221		s.cursors[c] = struct{}{}
222		s.cursorMu.Unlock()
223	}
224	
225	func (s *Store) unregisterCursor(c *Cursor) {
226		s.cursorMu.Lock()
227		delete(s.cursors, c)
228		s.cursorMu.Unlock()
229	}
230	
231	// newCursor materializes the cursor's ordered key list once, at open time,
232	// and registers it so compaction retains its versions.
233	func (s *Store) newCursor(v *view, start, end string) *Cursor {
234		c := newCursorPinned(s, v, start, end)
235		s.registerCursor(c)
236		return c
237	}
238	
239	func newCursorPinned(st *Store, v *view, start, end string) *Cursor {
240		return &Cursor{
241			store: st,
242			v:     v,
243			start: start,
244			end:   end,
245			keys:  presentKeys(*v, start, end),
246		}
247	}
248	
249	// newEmptyCursor returns a never-erroring cursor over nothing, used when a
250	// cursor is opened over an empty/closed view. It pins no versions.
251	func newEmptyCursor() *Cursor {
252		empty := make(view)
253		return &Cursor{v: &empty, keys: nil}
254	}
255	
256	// ---- ordered reads over immutable views ----
257	
258	func scanView(v view, start, end string, limit int) []KVPair {
259		keys := presentKeys(v, start, end)
260		if limit > 0 && len(keys) > limit {
261			keys = keys[:limit]
262		}
263		out := make([]KVPair, 0, len(keys))
264		for _, k := range keys {
265			n := v[k]
266			out = append(out, KVPair{Key: k, Value: cloneBytes(n.value)})
267		}
268		return out
269	}
270	
271	// presentKeys returns the present keys in [start,end) sorted by byte order.
272	// Go's string ordering is unsigned byte ordering on the raw contents.
273	func presentKeys(v view, start, end string) []string {
274		keys := make([]string, 0, len(v))
275		for k, n := range v {
276			if n == nil || !n.present {
277				continue
278			}
279			if start != "" && k < start {
280				continue
281			}
282			if end != "" && k >= end {
283				continue
284			}
285			keys = append(keys, k)
286		}
287		sort.Strings(keys)
288		return keys
289	}
