291	// validInterval reports whether [start,end) can hold keys. An empty bound is
292	// unbounded; with both given, start must be strictly before end.
293	func validInterval(start, end string) bool {
294		if start == "" || end == "" {
295			return true
296		}
297		return start < end
298	}
299	
300	// prefixEnd returns the smallest key strictly greater than every key having
301	// prefix: drop trailing 0xFF bytes and increment the last remaining byte. A
302	// prefix of all 0xFF bytes (and the empty prefix) has no upper bound.
303	func prefixEnd(prefix string) string {
304		if prefix == "" {
305			return ""
306		}
307		end := []byte(prefix)
308		for len(end) > 0 && end[len(end)-1] == 0xFF {
309			end = end[:len(end)-1]
310		}
311		if len(end) == 0 {
312			return ""
313		}
314		end[len(end)-1]++
315		return string(end)
