1	package snapshot
2	
3	import (
4		"errors"
5		"fmt"
6		"io/fs"
7		"os"
8		"path/filepath"
9		"sync"
10		"testing"
11	)
12	
13	func walSize(t *testing.T, dir string) int64 {
14		t.Helper()
15		info, err := os.Stat(filepath.Join(dir, walName))
16		if err != nil {
17			t.Fatalf("stat wal: %v", err)
18		}
19		return info.Size()
20	}
21	
22	func TestCompactReclaimsDiskHistory(t *testing.T) {
23		dir := tempDir(t)
24		s := openStore(t, dir)
25	
26		if err := s.Put("a", []byte("v1")); err != nil {
27			t.Fatal(err)
28		}
29		if err := s.Put("b", []byte("doomed")); err != nil {
30			t.Fatal(err)
31		}
32		pinned, err := s.Snapshot() // pins v1 of "a" and live "b"
33		if err != nil {
34			t.Fatal(err)
35		}
36	
37		big := make([]byte, 4096)
38		for i := range big {
39			big[i] = byte(i)
40		}
41		// Many overwrites and a delete: all of this is reclaimable history on
42		// disk, none of it belongs to the pinned snapshot.
43		for i := 0; i < 20; i++ {
44			if err := s.Put("a", big); err != nil {
45				t.Fatal(err)
46			}
47		}
48		if err := s.Put("c", []byte("kept")); err != nil {
49			t.Fatal(err)
50		}
51		if err := s.Delete("b"); err != nil {
52			t.Fatal(err)
53		}
54		for i := 0; i < 3; i++ {
55			if _, err := s.Snapshot(); err != nil {
56				t.Fatal(err)
57			}
58		}
59	
60		statsBefore := s.Stats()
61		sizeBefore := walSize(t, dir)
62	
63		if err := s.Compact(); err != nil {
64			t.Fatalf("compact: %v", err)
65		}
66	
67		if _, err := os.Stat(filepath.Join(dir, compactTmpName)); !errors.Is(err, fs.ErrNotExist) {
68			t.Fatalf("temporary compaction file left behind: %v", err)
69		}
70		sizeAfter := walSize(t, dir)
71		if sizeAfter >= sizeBefore {
72			t.Fatalf("wal did not shrink: before=%d after=%d", sizeBefore, sizeAfter)
73		}
74	
75		// Stats three numbers are unchanged by compaction.
76		statsAfter := s.Stats()
77		if statsAfter != statsBefore {
78			t.Fatalf("stats changed: before=%+v after=%+v", statsBefore, statsAfter)
79		}
80	
81		// The open snapshot's fixed view is byte-identical.
82		if got, ok := pinned.Get("a"); !ok || string(got) != "v1" {
83			t.Fatalf("pinned a: %q ok=%v", got, ok)
84		}
85		if got, ok := pinned.Get("b"); !ok || string(got) != "doomed" {
86			t.Fatalf("pinned deleted b: %q ok=%v", got, ok)
87		}
88		if _, ok := pinned.Get("c"); ok {
89			t.Fatal("pinned snapshot sees key created after it")
90		}
91	
92		// Latest view: miss/hit semantics unchanged.
93		if got, ok, err := s.Get("a"); !ok || err != nil || len(got) != len(big) {
94			t.Fatalf("latest a: len=%d ok=%v err=%v", len(got), ok, err)
95		} else {
96			for i := range big {
97				if got[i] != big[i] {
98					t.Fatalf("latest a torn at %d", i)
99				}
100			}
101		}
102		if got, ok, _ := s.Get("c"); !ok || string(got) != "kept" {
103			t.Fatalf("latest c: %q ok=%v", got, ok)
104		}
105		if _, ok, _ := s.Get("b"); ok {
106			t.Fatal("deleted key is a hit after compaction")
107		}
108		if _, ok, _ := s.Get("never"); ok {
109			t.Fatal("unknown key is a hit after compaction")
110		}
111	
112		if err := s.Close(); err != nil {
113			t.Fatal(err)
114		}
115	
116		// Reopen: committed state is complete, snapshot count never reset.
117		s2, err := Open(dir)
118		if err != nil {
119			t.Fatal(err)
120		}
121		defer s2.Close()
122		if got, ok, _ := s2.Get("c"); !ok || string(got) != "kept" {
123			t.Fatalf("after reopen c: %q ok=%v", got, ok)
124		}
125		if _, ok, _ := s2.Get("b"); ok {
126			t.Fatal("deletion lost across reopen")
127		}
128		if st := s2.Stats(); st != statsBefore {
129			t.Fatalf("stats after reopen: %+v want %+v", st, statsBefore)
130		}
131		if n := s2.Stats().Snapshots; n != 4 {
132			t.Fatalf("snapshot count after reopen: %d, want 4", n)
133		}
134	
135		// New commits append to the compacted log and survive another reopen.
136		if err := s2.Put("d", []byte("post")); err != nil {
137			t.Fatal(err)
138		}
139		if err := s2.Close(); err != nil {
140			t.Fatal(err)
141		}
142		s3, err := Open(dir)
143		if err != nil {
144			t.Fatal(err)
145		}
146		defer s3.Close()
147		if got, ok, _ := s3.Get("d"); !ok || string(got) != "post" {
148			t.Fatalf("post-compact commit lost: %q ok=%v", got, ok)
149		}
150		if n := s3.Stats().Snapshots; n != 4 {
151			t.Fatalf("snapshot count changed: %d", n)
152		}
153	
154		// The pinned snapshot even outlives its store and still reads identically.
155		if got, ok := pinned.Get("a"); !ok || string(got) != "v1" {
156			t.Fatalf("pinned view changed: %q ok=%v", got, ok)
157		}
158		if err := pinned.Close(); err != nil {
159			t.Fatal(err)
160		}
161	}
162	
163	func TestCompactDropsInMemoryHistory(t *testing.T) {
164		s := openStore(t, tempDir(t))
165	
166		if err := s.Put("k", []byte("old1")); err != nil {
167			t.Fatal(err)
168		}
169		if err := s.Put("k", []byte("old2")); err != nil {
170			t.Fatal(err)
171		}
172		if err := s.Put("k", []byte("new")); err != nil {
173			t.Fatal(err)
174		}
175		if err := s.Put("gone", []byte("x")); err != nil {
176			t.Fatal(err)
177		}
178		if err := s.Delete("gone"); err != nil {
179			t.Fatal(err)
180		}
