186		v := *s.current.Load()
187		for key, n := range v {
188			if n.older != nil {
189				t.Fatalf("current node for %q still keeps history after compaction", key)
190			}
191		}
192		if n := v["gone"]; n != nil {
193			t.Fatalf("deleted key retained a node in compacted view: %+v", n)
194		}
