200	func TestCompactEmptyValuesStayHits(t *testing.T) {
201		dir := tempDir(t)
202		s := openStore(t, dir)
203		for i, v := range [][]byte{nil, {}} {
204			if err := s.Put(fmt.Sprintf("e%d", i), v); err != nil {
205				t.Fatal(err)
206			}
