432	func TestCommitBatchCompactionKeepsIntraBatchOrder(t *testing.T) {
433		dir := tempDir(t)
434		s := openStore(t, dir)
435	
436		if err := s.Put("k", []byte("v1")); err != nil {
437			t.Fatal(err)
438		}
439		// This cursor pins v1; the batch then touches k three times. Its middle
440		// value was never visible to any whole-batch view and is reclaimable, but
441		// the retained pair (pinned v1, post-batch head v3) must survive the log
442		// rewrite linked oldest-to-newest in the right order.
443		cursor, err := s.OpenCursorPrefix("")
444		if err != nil {
445			t.Fatal(err)
446		}
447		if err := s.CommitBatch([]BatchOp{
448			{Key: "k", Value: make([]byte, 4096)},
449			{Key: "k", Value: []byte("middle")},
450			{Key: "k", Value: []byte("v3")},
451			{Key: "other", Value: []byte("o1")},
452			{Key: "other", Value: []byte("o2")},
453		}); err != nil {
454			t.Fatal(err)
455		}
456		if err := s.Compact(); err != nil {
457			t.Fatalf("compact after batch: %v", err)
458		}
459		if got, ok, _ := s.Get("k"); !ok || string(got) != "v3" {
460			t.Fatalf("k after compact: %q ok=%v", got, ok)
461		}
462		if got, ok, _ := s.Get("other"); !ok || string(got) != "o2" {
463			t.Fatalf("other after compact: %q ok=%v", got, ok)
464		}
465		pinned, err := cursor.Page(0, 10)
466		if err != nil {
467			t.Fatal(err)
468		}
469		if len(pinned) != 1 || string(pinned[0].Value) != "v1" {
470			t.Fatalf("pinned cursor changed: %+v", pinned)
471		}
472		cursor.Close()
473		if err := s.Close(); err != nil {
474			t.Fatal(err)
475		}
476	
477		// Replay the compacted log: retained per-key histories must survive in
478		// ascending sequence order, with no seq duplicated or reordered.
479		s2, err := Open(dir)
480		if err != nil {
481			t.Fatal(err)
482		}
483		defer s2.Close()
484		if got, ok, _ := s2.Get("k"); !ok || string(got) != "v3" {
485			t.Fatalf("k after reopen: %q ok=%v", got, ok)
486		}
487		chains, values := replayChains(t, dir)
488		if seqs := chains["k"]; len(seqs) != 2 {
489			t.Fatalf("k retained history after compaction: %v, want 2 versions", seqs)
490		} else if seqs[0] >= seqs[1] {
491			t.Fatalf("batch versions split or reordered in compacted log: %v", seqs)
492		}
493		if values[keySeq{"k", chains["k"][0]}] != "v1" || values[keySeq{"k", chains["k"][1]}] != "v3" {
494			t.Fatalf("retained values mismatch: %+v", values)
495		}
496	}
