498	type keySeq struct {
499		key string
500		seq uint64
501	}
502	
503	func replayChains(t *testing.T, dir string) (map[string][]uint64, map[keySeq]string) {
504		t.Helper()
505		chains := make(map[string][]uint64)
506		values := make(map[keySeq]string)
507		seen := make(map[uint64]bool)
508		_, _, err := replayWAL(dir, func(op byte, key string, value []byte, seq uint64) {
509			switch op {
510			case opPutSeq, opDeleteSeq:
511				if seen[seq] {
512					t.Fatalf("duplicate seq %d on key %q during replay", seq, key)
513				}
514				seen[seq] = true
515				chains[key] = append(chains[key], seq)
516				if op == opPutSeq {
517					values[keySeq{key, seq}] = string(value)
518				}
519			}
520		})
521		if err != nil {
522			t.Fatal(err)
523		}
524		return chains, values
525	}
