575		var total int64
576		for _, e := range entries {
577			if info, err := e.Info(); err == nil && !e.IsDir() {
578				total += info.Size()
579			}
580		}
581		return total
582	}
583	
584	// ---- concurrency ----
585	
586	func queueLen(s *Store) int {
587		s.queueMu.Lock()
588		defer s.queueMu.Unlock()
589		return len(s.queue)
590	}
591	
592	func walSyncs(s *Store) int {
593		s.mu.Lock()
594		defer s.mu.Unlock()
595		if s.wal == nil {
596			return -1
597		}
598		return s.wal.syncs
599	}
600	
601	func TestCommitBatchGroupCommitSharesOneSync(t *testing.T) {
602		s := openStore(t, tempDir(t))
603	
604		const followers = 7
605		proceed := make(chan struct{})
606		var leaderWG sync.WaitGroup
607		leaderWG.Add(1)
608		s.leaderHook = func() {
609			leaderWG.Done()
610			<-proceed
611		}
612		defer func() { s.leaderHook = nil }()
613	
614		leaderErr := make(chan error, 1)
615		go func() {
616			leaderErr <- s.CommitBatch([]BatchOp{{Key: "leader", Value: []byte("L")}})
617		}()
618		leaderWG.Wait() // the leader is elected and parked before its first drain
619	
620		var wg sync.WaitGroup
621		for i := 0; i < followers; i++ {
622			wg.Add(1)
623			go func(i int) {
624				defer wg.Done()
625				if err := s.CommitBatch([]BatchOp{{Key: fmt.Sprintf("f%d", i), Value: []byte("F")}}); err != nil {
626					t.Errorf("follower %d: %v", i, err)
627				}
628			}(i)
629		}
630	
631		// Wait until every follower is queued behind the parked leader.
632		deadline := time.Now()
633		for queueLen(s) != followers+1 {
634			if time.Since(deadline) > 5*time.Second {
635				t.Fatalf("followers did not coalesce: queue=%d", queueLen(s))
636			}
637			runtime.Gosched()
638		}
639		before := walSyncs(s)
640		close(proceed)
641	
642		if err := <-leaderErr; err != nil {
643			t.Fatalf("leader: %v", err)
644		}
645		wg.Wait()
646		after := walSyncs(s)
647	
648		// All 8 batches returned, one view per batch committed, but exactly one
649		// durable force covered the whole coalesced group.
650		if after-before != 1 {
651			t.Fatalf("group commit used %d syncs for %d batches, want 1", after-before, followers+1)
652		}
653		if got, ok, _ := s.Get("leader"); !ok || string(got) != "L" {
654			t.Fatalf("leader value: %q ok=%v", got, ok)
655		}
656		for i := 0; i < followers; i++ {
657			if got, ok, _ := s.Get(fmt.Sprintf("f%d", i)); !ok || string(got) != "F" {
658				t.Fatalf("follower %d value: %q ok=%v", i, got, ok)
659			}
660		}
661	}
662	
663	func TestCommitBatchConcurrent(t *testing.T) {
664		s := openStore(t, tempDir(t))
665	
666		const n = 16
667		const rounds = 50
668		var wg sync.WaitGroup
669		for g := 0; g < n; g++ {
670			wg.Add(1)
671			go func(g int) {
672				defer wg.Done()
673				for r := 0; r < rounds; r++ {
674					err := s.CommitBatch([]BatchOp{
675						{Key: fmt.Sprintf("priv-%d", g), Value: []byte(fmt.Sprintf("x%d", r))},
676						{Key: "shared", Value: []byte(fmt.Sprintf("%d-%d", g, r))},
677						{Key: fmt.Sprintf("priv-%d", g), Value: []byte("y")},
678					})
679					if err != nil {
680						t.Errorf("batch: %v", err)
681						return
682					}
683				}
684			}(g)
685		}
686		for c := 0; c < 2; c++ {
687			wg.Add(1)
688			go func() {
689				defer wg.Done()
690				for i := 0; i < 25; i++ {
691					if err := s.Compact(); err != nil {
692						t.Errorf("compact: %v", err)
693						return
694					}
695				}
696			}()
697		}
698		wg.Wait()
699	
700		// Every per-goroutine key ends at its last value; shared lands on exactly
701		// one committed value.
702		for g := 0; g < n; g++ {
703			if got, ok, _ := s.Get(fmt.Sprintf("priv-%d", g)); !ok || string(got) != "y" {
704				t.Fatalf("priv-%d: %q ok=%v", g, got, ok)
705			}
706		}
707		if got, ok, _ := s.Get("shared"); !ok || len(got) == 0 {
708			t.Fatalf("shared missing after concurrent batches: ok=%v", ok)
709		}
710		if st := s.Stats(); st.Keys != n+1 {
711			t.Fatalf("stats keys=%d, want %d", st.Keys, n+1)
712		}
713		if err := s.Compact(); err != nil {
714			t.Fatal(err)
715		}
716		if err := s.Compact(); err != nil {
717			t.Fatalf("repeated compact: %v", err)
718		}
719	}
720	
721	func TestCommitBatchConcurrentDurability(t *testing.T) {
722		dir := tempDir(t)
723		s := openStore(t, dir)
724	
725		const n = 12
726		const rounds = 40
727		var wg sync.WaitGroup
728		for g := 0; g < n; g++ {
729			wg.Add(1)
730			go func(g int) {
731				defer wg.Done()
732				for r := 0; r < rounds; r++ {
733					if err := s.CommitBatch([]BatchOp{
734						{Key: fmt.Sprintf("k%d", g%4), Value: []byte(fmt.Sprintf("%d:%d", g, r))},
735						{Key: fmt.Sprintf("u%d", g), Value: []byte(fmt.Sprintf("%d", r))},
736					}); err != nil {
737						t.Errorf("batch: %v", err)
738						return
739					}
740				}
741			}(g)
742		}
743		wg.Wait()
744		memBefore := s.Stats()
745		if err := s.Close(); err != nil {
746			t.Fatal(err)
747		}
748	
749		s2, err := Open(dir)
750		if err != nil {
751			t.Fatal(err)
752		}
753		defer s2.Close()
754		if got := s2.Stats(); got != memBefore {
755			t.Fatalf("stats differ after reopen: %+v want %+v", got, memBefore)
756		}
757		for g := 0; g < n; g++ {
758			if got, ok, _ := s2.Get(fmt.Sprintf("u%d", g)); !ok || string(got) != fmt.Sprintf("%d", rounds-1) {
759				t.Fatalf("u%d after reopen: %q ok=%v", g, got, ok)
760			}
761		}
762		// No sequence may appear twice anywhere in the replayed history.
763		chains, _ := replayChains(t, dir)
764		for k, seqs := range chains {
765			for i := 1; i < len(seqs); i++ {
766				if seqs[i] <= seqs[i-1] {
767					t.Fatalf("key %s chain out of order after reopen: %v", k, seqs)
768				}
769			}
770		}
771	}
772	
773	// ---- stats comparison ----
774	
775	func TestCommitBatchStatsBeforeAfter(t *testing.T) {
776		s := openStore(t, tempDir(t))
777		if err := s.Put("a", []byte("aaaa")); err != nil {
778			t.Fatal(err)
779		}
780		before := s.Stats()
781		if err := s.CommitBatch([]BatchOp{
782			{Key: "b", Value: []byte("bb")},
783			{Key: "c", Value: []byte("cc")},
784			{Key: "a", Value: []byte("aaaaaa")},
785			{Key: "d", Value: []byte("x")},
786			{Key: "d", Delete: true},
787		}); err != nil {
788			t.Fatal(err)
789		}
790		after := s.Stats()
791		if after.Keys != before.Keys+2 {
792			t.Fatalf("keys: before=%d after=%d", before.Keys, after.Keys)
793		}
794		// (6+2+2)/3 = 3.333... -> 3.33
795		if after.AvgBytes != 3.33 {
796			t.Fatalf("avg bytes: %v, want 3.33", after.AvgBytes)
797		}
798		if after.Snapshots != before.Snapshots {
799			t.Fatal("commit batch changed snapshot count")
800		}
801	}
