1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"fmt"
10		"io/fs"
11		"os"
12		"sort"
13		"sync"
14		"sync/atomic"
15	)
16	
17	// node is one immutable version in a key's history. Versions form a linked
18	// list from newest to oldest; a snapshot pins the head current when it was
19	// acquired, so overwritten and deleted values stay readable through every
20	// view that references them. seq is the version's commit number, unique and
21	// strictly increasing along each key's chain; it orders versions across the
22	// independent chains that meet again during a pinning compaction.
23	type node struct {
24		value   []byte
25		present bool   // false marks a delete; a present nil/empty value is still a hit
26		seq     uint64 // commit order, 1-based
27		older   *node
28	}
29	
30	// view is an immutable map of keys to their newest version. Updates produce a
31	// fresh map; the current view and every snapshot simply point at one. Views
32	// are never mutated after publication, so reading them needs no lock. The
33	// maps share version chains with their successor views.
34	type view map[string]*node
35	
36	// Store is an open key-value store backed by a directory on disk.
37	type Store struct {
38		mu sync.Mutex // serializes writers and guards the fields below
39	
40		dir       string
41		wal       *walWriter
42		current   atomic.Pointer[view] // latest committed view; lock-free for readers
43		snapshots atomic.Uint64        // cumulative number of snapshots handed out
44		nextSeq   uint64               // highest commit sequence handed out; guarded by mu
45	
46		// Open cursors pin their fixed view's versions against compaction. The
47		// set is read by Compact (which holds mu) and mutated at cursor
48		// open/close, using cursorMu; reads never take either lock.
49		cursorMu sync.Mutex
50		cursors  map[*Cursor]struct{}
51	
52		// Group-commit queue. Batches that arrive while another commit is
53		// forcing the log line up here; one leader drains the queue, encodes the
54		// waiting batches and shares a single flush plus fsync across them.
55		// queueMu only ever guards this queue and committer; it is never held
56		// across disk I/O, so readers and enqueuers never wait on a sync.
57		queueMu   sync.Mutex
58		queue     []*pendingBatch
59		committer bool
60	
61		// Test hook, nil outside tests. leaderHook runs once after a batch has
62		// become leader, before its first queue drain, and lets tests hold a
63		// leader until a known number of batches have coalesced.
64		leaderHook func()
65	
66		closed atomic.Bool
67	}
68	
69	// Snapshot is a stable read-only view of a store captured at one instant. It
70	// owns no store resources of its own and stays usable after the store has
71	// been closed; a cursor opened from it does register with the store while it
72	// pins versions.
73	type Snapshot struct {
74		v     atomic.Pointer[view] // nil once the snapshot is closed
75		store *Store               // back-reference for cursor pin accounting
76	}
77	
78	// Open opens or creates a persistent store in dir. A path that names a
79	// regular file rather than a directory returns an error wrapping
80	// fs.ErrInvalid.
81	func Open(dir string) (*Store, error) {
82		info, err := os.Stat(dir)
83		if err == nil {
84			if !info.IsDir() {
85				return nil, errNotDir
86			}
87		} else {
88			if !errors.Is(err, fs.ErrNotExist) {
89				return nil, err
90			}
91			if err := os.MkdirAll(dir, 0o700); err != nil {
92				return nil, err
93			}
94		}
95	
96		// A replacement log from a compaction killed before its rename can never
97		// be complete state of record; the old wal.log is. Drop the stale file.
98		if err := removeStaleCompact(dir); err != nil {
99			return nil, err
100		}
101	
102		latest := make(view)
103		var replaySeq uint64
104		validSize, snapshotCount, err := replayWAL(dir, func(op byte, key string, value []byte, seq uint64) {
105			// Legacy records (written before sequence numbers existed) carry no
106			// seq; replay order is commit order, so number them sequentially.
107			if seq == 0 {
108				replaySeq++
109				seq = replaySeq
110			} else if seq > replaySeq {
111				replaySeq = seq
112			}
113			switch op {
114			case opPut, opPutSeq:
115				latest[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: latest[key]}
116			case opDelete, opDeleteSeq:
117				latest[key] = &node{present: false, seq: seq, older: latest[key]}
118			}
119		})
120		if err != nil {
121			return nil, err
122		}
123	
124		wal, err := openWALWriter(dir, validSize)
125		if err != nil {
126			return nil, err
127		}
128	
129		s := &Store{dir: dir, wal: wal, cursors: make(map[*Cursor]struct{}), nextSeq: replaySeq}
130		s.snapshots.Store(snapshotCount)
131		s.current.Store(&latest)
132		return s, nil
133	}
134	
135	// Put stores value under key. An empty key returns an error wrapping
136	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
137	// key reports a hit. The store does not keep a reference to value.
138	func (s *Store) Put(key string, value []byte) error {
139		s.mu.Lock()
140		defer s.mu.Unlock()
141		if s.closed.Load() {
142			return errStoreClosed
143		}
144		if key == "" {
145			return errEmptyKey
146		}
147		seq := s.nextSeq + 1
148		if err := s.wal.appendPut(key, value, seq); err != nil {
149			return err
150		}
151		s.nextSeq = seq
152		next := s.deriveView()
153		next[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: (*s.current.Load())[key]}
154		s.current.Store(&next)
155		return nil
156	}
157	
158	type pendingBatch struct {
159		ops  []BatchOp
160		done chan error // buffered(1); the leader delivers the commit result
161	}
162	
163	// commitPlan is one queued batch resolved against the cumulative state built
164	// up across its whole sync group.
165	type commitPlan struct {
166		view view // cumulative view after this batch; nil when it committed nothing
167	}
168	
169	// BatchOp is one change in a batch committed with CommitBatch. Delete false
170	// stores Value under Key (a nil or empty Value is still a hit); Delete true
171	// removes Key.
172	type BatchOp struct {
173		Key    string
174		Value  []byte
175		Delete bool
176	}
177	
178	// CommitBatch applies a group of writes and deletes as one atomic commit:
179	// the whole batch becomes visible together or not at all, and snapshots and
180	// cursors fixed at any instant see either the state before the batch or the
181	// state after it, never an in-between mixture. Changes are applied in list
182	// order; a later change to the same key overrides an earlier one within the
183	// batch. Concurrent batches take effect in commit (enqueue) order, and a
184	// later committed batch's same-key change overrides an earlier one's.
185	//
186	// Batches committed concurrently share the disk sync: one leader drains the
187	// queue, encodes every waiting batch as its own recoverable framed commit
188	// and forces them all with one flush plus fsync, so N batches arriving
189	// together cost one sync while each stays whole on recovery; a batch that
190	// arrives while a sync is in flight rides the next one. Reads take none of
191	// these locks and are never blocked by the sync.
192	//
193	// If any change has an empty key the whole batch is rejected before it is
194	// queued or committed: an error wrapping fs.ErrInvalid is returned, no frame
195	// is written and the store's state is unchanged. A delete of a key that is
196	// absent or already deleted commits nothing, exactly like Delete; a batch
197	// containing only such no-ops (or an empty slice) commits nothing and
198	// returns nil. CommitBatch on a closed store returns an error wrapping
199	// fs.ErrClosed.
200	//
201	// Each batch is forced to stable storage before its call returns and is
202	// published as one new view; a process killed mid-commit therefore reopens
203	// with the entire batch present or entirely absent. The store does not keep
204	// references to the op Value slices after return.
205	func (s *Store) CommitBatch(ops []BatchOp) error {
206		if s.closed.Load() {
207			return errStoreClosed
208		}
209		if err := validateBatchOps(ops); err != nil {
210			return err
211		}
212	
213		me := &pendingBatch{ops: ops, done: make(chan error, 1)}
214	
215		// Enqueue. queueMu guards only the queue and the leader flag and is
216		// never held across disk I/O, so followers can join a group while the
217		// leader is syncing and readers never wait.
218		s.queueMu.Lock()
219		if s.closed.Load() {
220			s.queueMu.Unlock()
221			return errStoreClosed
222		}
223		s.queue = append(s.queue, me)
224		if s.committer {
225			s.queueMu.Unlock()
226			return <-me.done // the running leader will drain this batch
227		}
228		s.committer = true
229		s.queueMu.Unlock()
230	
231		// Test-only rendezvous: invoked once by the elected leader before its
232		// first queue drain. Production leaves it nil.
233		if s.leaderHook != nil {
234			s.leaderHook()
235		}
236	
237		// Leadership: drain groups until the queue is empty. Each group takes
238		// s.mu while it forces the log, which serializes it with Put, Delete,
239		// Snapshot, Compact and Close, so a group never straddles a log swap.
240		for {
241			s.queueMu.Lock()
242			// Resign and re-check the queue under one critical section, so a
243			// batch enqueuing in this instant either observes the still-active
244			// leader or becomes the next one; no batch can be left queued with
245			// no leader to drain it.
246			if len(s.queue) == 0 {
247				s.committer = false
248				s.queueMu.Unlock()
249				break
250			}
251			group := s.queue
252			s.queue = nil
253			s.queueMu.Unlock()
254			for p, err := range s.commitGroup(group) {
255				group[p].done <- err
256			}
257		}
258	
259		return <-me.done
260	}
261	
262	// validateBatchOps checks argument-only invariants before a batch is queued.
263	// Empty keys map to fs.ErrInvalid, exactly as for Put and Delete.
264	func validateBatchOps(ops []BatchOp) error {
265		for i := range ops {
266			if ops[i].Key == "" {
267				return errEmptyKey
268			}
269		}
270		for i := range ops {
271			if len(ops[i].Key) > maxRecord || (!ops[i].Delete && seqSize+len(ops[i].Value) > maxRecord) {
272				return fmt.Errorf("snapshot: record too large")
273			}
274		}
275		return nil
276	}
277	
278	// commitGroup encodes and forces every queued batch with one flush and one
279	// sync, then publishes one view per effective batch in queue (commit) order.
280	// It returns one result per batch. An encoding or sync failure fails the
281	// whole group: nothing it contained is published or sequenced. The single
282	// committer calls this; s.mu is taken for the entire force, exactly as the
283	// single-key commit path does.
284	func (s *Store) commitGroup(group []*pendingBatch) []error {
285		results := make([]error, len(group))
286	
287		s.mu.Lock()
288		defer s.mu.Unlock()
289		if s.closed.Load() || s.wal == nil {
290			// Close ran between the drain and the lock; nothing can commit.
291			for i := range results {
292				results[i] = errStoreClosed
293			}
294			return results
295		}
296	
297		// Remember where the group starts so any failure can rewind the log:
298		// unacknowledged frames must not linger at EOF and reappear under a
299		// later commit or after a reopen. Nothing is buffered here (the previous
300		// group always flushed), so EOF is the exact offset.
301		groupStart, posErr := s.wal.position()
302		if posErr != nil {
303			for i := range results {
304				results[i] = posErr
305			}
306			return results
307		}
308		rollback := func(cause error) []error {
309			if err := s.wal.truncateTo(groupStart); err != nil {
310				cause = errors.Join(cause, err)
311			}
312			for i := range results {
313				results[i] = cause
314			}
315			return results
316		}
317	
318		next := *s.current.Load()
319		seq := s.nextSeq
320		plans := make([]commitPlan, 0, len(group))
321		encodedAny := false
322	
323		for _, p := range group {
324			// Each batch gets its own cumulative, immutable map, so the view it
325			// publishes is a valid point-in-time state independent of later
326			// batches in the group.
327			view := make(view, len(next)+len(p.ops))
328			for k, v := range next {
329				view[k] = v
330			}
331			var changes []batchChange
332			for i := range p.ops {
333				op := &p.ops[i]
334				head := view[op.Key]
335				if op.Delete {
336					if head == nil || !head.present {
337						continue // idempotent no-op, matching the single Delete
338					}
339					seq++
340					changes = append(changes, batchChange{key: op.Key, seq: seq, delete: true})
341					view[op.Key] = &node{present: false, seq: seq, older: head}
342				} else {
343					seq++
344					value := cloneBytes(op.Value)
345					changes = append(changes, batchChange{key: op.Key, seq: seq, value: value})
346					view[op.Key] = &node{value: value, present: true, seq: seq, older: head}
347				}
348			}
349			if len(changes) > 0 {
350				if err := s.wal.encodeBatch(changes); err != nil {
351					return rollback(err)
352				}
353				encodedAny = true
354			}
355			plans = append(plans, commitPlan{view: ternaryView(len(changes) > 0, view)})
356			next = view
357		}
358	
359		if encodedAny {
360			// One flush, one fsync for the whole group. Return means every
361			// encoded batch in it is durable as a self-contained framed commit.
362			if err := s.wal.flushSync(); err != nil {
363				return rollback(err)
364			}
365		}
366	
367		s.nextSeq = seq
368		for _, plan := range plans {
369			if plan.view != nil {
370				s.current.Store(&plan.view)
371			}
372		}
373		return results
374	}
375	
376	// ternaryView returns v when ok, nil otherwise.
377	func ternaryView(ok bool, v view) view {
378		if ok {
379			return v
380		}
381		return nil
382	}
383	
384	// Get returns the latest committed value for key. Empty keys, keys never
385	// written and deleted keys are all misses: ok is false and err is nil. The
386	// returned bytes are owned by the caller.
387	func (s *Store) Get(key string) ([]byte, bool, error) {
388		if s.closed.Load() {
389			return nil, false, errStoreClosed
390		}
391		if key == "" {
392			return nil, false, nil
393		}
394		val, ok := lookup(*s.current.Load(), key)
395		return val, ok, nil
396	}
397	
398	// Delete removes key. Deleting an empty key returns an error wrapping
399	// fs.ErrInvalid; deleting a key that was never written or is already deleted
400	// is not an error and commits nothing.
401	func (s *Store) Delete(key string) error {
402		s.mu.Lock()
403		defer s.mu.Unlock()
404		if s.closed.Load() {
405			return errStoreClosed
406		}
407		if key == "" {
408			return errEmptyKey
409		}
410		cur := *s.current.Load()
411		if n := cur[key]; n == nil || !n.present {
412			return nil // nothing live to delete: idempotent no-op
413		}
414		seq := s.nextSeq + 1
415		if err := s.wal.appendDelete(key, seq); err != nil {
416			return err
417		}
418		s.nextSeq = seq
419		next := s.deriveView()
420		next[key] = &node{present: false, seq: seq, older: cur[key]}
421		s.current.Store(&next)
422		return nil
423	}
424	
425	// deriveView returns a shallow, mutable copy of the current view. Callers
426	// must hold s.mu and publish the result through s.current before unlocking.
427	func (s *Store) deriveView() view {
428		cur := *s.current.Load()
429		next := make(view, len(cur)+1)
430		for k, v := range cur {
431			next[k] = v
432		}
433		return next
434	}
435	
436	// Compact reclaims history: values that were overwritten or deleted and are
437	// not needed by any open snapshot or cursor are dropped from memory and the
438	// write-ahead log is atomically rewritten, so the directory occupies less
439	// space than before whenever reclaimable history existed.
440	//
441	// Every open snapshot keeps its exact fixed view: its values are untouched
442	// and reads before and after compaction return byte-identical results. Every
443	// open cursor likewise keeps paging through its exact fixed sequence, and
444	// the one version per key its view shows stays in the rewritten log until
445	// the cursor closes; the compaction after that drops it and shrinks the
446	// directory further. A process killed at any point during compaction reopens
447	// in a complete commit state, with every successful write, deletion and the
448	// cumulative snapshot count intact; no intermediate file requires a second
449	// compaction to repair.
450	//
451	// Compact takes no arguments, may be called at any time and serializes with
452	// writes, deletes, snapshots, cursor opens, closing and other compactions;
453	// concurrent or repeated calls queue and all return nil. Compacting a closed
454	// store returns an error wrapping fs.ErrClosed.
455	func (s *Store) Compact() error {
456		s.mu.Lock()
457		defer s.mu.Unlock()
458		if s.closed.Load() {
459			return errStoreClosed
460		}
461	
462		cur := *s.current.Load()
463	
464		// Pinned versions, keyed by commit sequence (globally unique). The
465		// current head of every live key in the latest view is retained; each
466		// open cursor additionally pins the single head version its fixed view
467		// shows for every present key in its range. A deleted key's tombstone is
468		// retained only when a cursor still reads an older value under it, so
469		// replay links that value as the tombstone's predecessor; otherwise the
470		// key is dropped from the rewritten log altogether, as before.
471		pinned := make(map[uint64]*node)
472		keySeqs := make(map[string][]uint64)
473		cursorPins := make(map[string]bool)
474		pin := func(k string, n *node) {
475			if n == nil {
476				return
477			}
478			if _, ok := pinned[n.seq]; !ok {
479				pinned[n.seq] = n
480				keySeqs[k] = append(keySeqs[k], n.seq)
481			}
482		}
483		for _, c := range s.openCursors() {
484			v := *c.v
485			for _, k := range c.keys {
486				cursorPins[k] = true
487				pin(k, v[k]) // exactly the version this cursor pages out
488			}
489		}
490		for k, n := range cur {
491			if n.present || cursorPins[k] {
492				pin(k, n) // live head, or a tombstone shielding a pinned value
493			}
494		}
495	
496		// Emit one oldest-to-newest history per key so replay links the retained
497		// versions into the correct chains. A key deleted with no cursor reading
498		// an older value is absent from keySeqs altogether and drops out of both
499		// the new view and the rewritten log, exactly as in the baseline.
500		keys := make([]string, 0, len(keySeqs))
501		for k := range keySeqs {
502			keys = append(keys, k)
503		}
504		sort.Strings(keys)
505		histories := make([]keyHistory, 0, len(keys))
506		fresh := make(view, len(cur))
507		for _, k := range keys {
508			seqs := keySeqs[k]
509			sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
510			h := keyHistory{key: k, versions: make([]nodeVer, 0, len(seqs))}
511			for _, seq := range seqs {
512				n := pinned[seq]
513				h.versions = append(h.versions, nodeVer{
514					seq: seq, present: n.present, value: n.value,
515				})
516			}
517			histories = append(histories, h)
518	
519			// The new current view gets single-node heads: history nobody pins
520			// becomes unreachable from memory here, while open snapshots and
521			// cursors keep their own views and nodes alive.
522			head := pinned[seqs[len(seqs)-1]]
523			if head.present {
524				fresh[k] = &node{value: head.value, present: true, seq: head.seq}
525			}
526		}
527	
528		// The rewrite is crash-atomic and split into three phases so the live
529		// writer never holds the old wal.log open while it is being replaced:
530		//
531		//  1. build and sync the complete replacement in the temp name (the old
532		//     log and writer are untouched until this succeeds);
533		//  2. close the live writer so no descriptor occupies wal.log (renaming
534		//     over a still-open file is refused by some native filesystems);
535		//  3. atomically rename the temp over wal.log, force the directory and
536		//     open a writer on the new log.
537		//
538		// A failure before the rename leaves the old log and the store exactly
539		// as they were, so committing can continue and a later Compact retries.
540		// A non-nil next writer after install means the rename landed even if
541		// the final directory sync reported an error; adopt it (the old file is
542		// unlinked), publish the matching view and surface the sync error.
543		if err := buildCompactWAL(s.dir, histories, s.snapshots.Load()); err != nil {
544			return err
545		}
546		oldWAL := s.wal
547		if err := oldWAL.close(); err != nil {
548			// The replacement is still staged under the temp name and has not
549			// become state of record; remove it so no repair-only intermediate
550			// file lingers, then reopen a writer on the untouched old log.
551			removeStaleCompact(s.dir)
552			reopened, openErr := openWALWriter(s.dir, -1)
553			if openErr != nil {
554				return err // reopen itself failed; surface the close failure
555			}
556			s.wal = reopened
557			return err
558		}
559		nextWAL, renamed, installErr := installCompactWAL(s.dir)
560		if nextWAL == nil {
561			return installErr
562		}
563		s.wal = nextWAL
564		if renamed {
565			s.current.Store(&fresh)
566		}
567		return installErr
568	}
569	
570	// openCursors snapshots the set of currently open cursors. Cursor views and
571	// bounds are immutable after opening, so reading their fields here needs no
572	// per-cursor lock.
573	func (s *Store) openCursors() []*Cursor {
574		s.cursorMu.Lock()
575		defer s.cursorMu.Unlock()
576		cs := make([]*Cursor, 0, len(s.cursors))
577		for c := range s.cursors {
578			cs = append(cs, c)
579		}
580		return cs
581	}
582	
583	// Snapshot acquires a stable view. It never observes writes committed after
584	// it returns, and keeps serving that view regardless of later writes,
585	// deletes or Store.Close, until the Snapshot itself is closed.
586	func (s *Store) Snapshot() (*Snapshot, error) {
587		s.mu.Lock()
588		defer s.mu.Unlock()
589		if s.closed.Load() {
590			return nil, errStoreClosed
591		}
592		count := s.snapshots.Add(1)
593		if err := s.wal.appendMeta(count); err != nil {
594			s.snapshots.Add(^uint64(0))
595			return nil, err
596		}
597		snap := &Snapshot{store: s}
598		snap.v.Store(s.current.Load())
599		return snap, nil
600	}
601	
602	// Get reads key from the snapshot's fixed view. Old values overwritten or
603	// deleted afterwards are still readable; keys created afterwards, empty
604	// keys and keys absent or deleted when the snapshot was taken are misses. A
605	// read from a closed snapshot is also a plain miss, never an error. The
606	// returned bytes are owned by the caller.
607	func (s *Snapshot) Get(key string) ([]byte, bool) {
608		if key == "" {
609			return nil, false
610		}
611		v := s.v.Load()
612		if v == nil {
613			return nil, false // closed snapshot
614		}
615		n := (*v)[key]
616		if n == nil || !n.present {
617			return nil, false
618		}
619		return cloneBytes(n.value), true
620	}
621	
622	// Close releases the snapshot's fixed view. Closing more than once is a
623	// no-op returning nil.
624	func (s *Snapshot) Close() error {
625		s.v.Store(nil)
626		return nil
627	}
628	
629	// Close flushes and closes the store. Data already committed stays complete
630	// and readable after reopening the directory. Snapshots still open keep
631	// serving their fixed views until closed themselves; closing an already
632	// closed store is a no-op returning nil.
633	func (s *Store) Close() error {
634		s.mu.Lock()
635		if !s.closed.CompareAndSwap(false, true) {
636			s.mu.Unlock()
637			return nil
638		}
639		wal := s.wal
640		s.wal = nil
641		s.mu.Unlock()
642	
643		return wal.close()
644	}
645	
646	func lookup(v view, key string) ([]byte, bool) {
647		n := v[key]
648		if n == nil || !n.present {
649			return nil, false
650		}
651		return cloneBytes(n.value), true
652	}
653	
654	func cloneBytes(b []byte) []byte {
655		if b == nil {
656			return nil
657		}
658		c := make([]byte, len(b))
659		copy(c, b)
660		return c
661	}
662

