1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"fmt"
8		"hash/crc32"
9		"io"
10		"os"
11	)
12	
13	// On-disk write-ahead log.
14	//
15	// Every successful Put/Delete (and every successfully acquired Snapshot) is
16	// appended as one framed record and forced to stable storage before the call
17	// reports success, so reopening a directory always replays a prefix of
18	// complete records (never a half-written value) and the cumulative snapshot
19	// count is never reset.
20	//
21	// Frame layout, little-endian:
22	//
23	//	magic    uint32   recordMagic
24	//	op       byte     opPut, opDelete, opMeta, opPutSeq, opDeleteSeq,
25	//	                  opBatchBegin or opBatchEnd
26	//	keyLen   uint32
27	//	valLen   uint32
28	//	key      [keyLen]byte
29	//	value    [valLen]byte (absent for plain deletes)
30	//	crc      uint32   IEEE CRC-32 of all preceding frame bytes
31	//
32	// An opMeta record carries no key and an 8-byte little-endian value holding
33	// the cumulative number of snapshots handed out so far.
34	//
35	// opPut/opDelete are the original records and carry no sequence number; they
36	// remain readable forever so a directory written by an older version reopens
37	// unchanged. Records written by this version use the Seq variants instead:
38	// the value area is an 8-byte little-endian commit sequence number (unique
39	// and increasing per key) followed, for puts, by the actual value
40	// (valLen = 8 + len(value)). Sequence numbers let a pinning compaction merge
41	// versions from several eras into one history while keeping their order.
42	//
43	// A batch is one opBatchBegin marker (empty key, empty value), the Seq frames
44	// of its effective changes in list order, and one opBatchEnd marker (empty
45	// key, 8-byte value holding the number of inner frames). The markers frame
46	// the atomic commit: replay applies the inner frames only once the complete,
47	// intact end marker is seen, so a crash that leaves anything short of it
48	// discards the whole batch down to the begin offset. The whole frame group
49	// is buffered and forced with a single flush plus a single sync, so return
50	// from the append means the entire batch is stable.
51	const (
52		walName = "wal.log"
53		// compactTmpName holds a freshly built log during compaction; it is
54		// atomically renamed over wal.log and never observed directly. A file by
55		// this name left behind by a crash mid-compaction is stale and removed on
56		// the next open.
57		compactTmpName = "wal.log.compact"
58	
59		recordMagic  uint32 = 0x534e4150 // "SNAP"
60		opPut        byte   = 1
61		opDelete     byte   = 2
62		opMeta       byte   = 3
63		opPutSeq     byte   = 4
64		opDeleteSeq  byte   = 5
65		opBatchBegin byte   = 6
66		opBatchEnd   byte   = 7
67	
68		frameHeaderSize = 4 + 1 + 4 + 4
69		crcSize         = 4
70		metaValueSize   = 8
71		seqSize         = 8
72		maxRecord       = 1 << 30 // sanity bound on key and value lengths
73	)
74	
75	type walWriter struct {
76		f *os.File
77		w *bufio.Writer
78	
79		// syncs counts durable forces (flush + fsync pairs). Groups commit many
80		// batches per increment; it is read by tests while the store lock is
81		// held and otherwise carries no semantics.
82		syncs int
83	}
84	
85	func openWALWriter(dir string, replaySize int64) (*walWriter, error) {
86		f, err := os.OpenFile(dir+string(os.PathSeparator)+walName, os.O_RDWR|os.O_CREATE, 0o600)
87		if err != nil {
88			return nil, err
89		}
90		// Drop any torn tail that replay could not consume. A negative replaySize
91		// means the file is already exactly what should be on disk (e.g. a log
92		// just installed by compaction) and must not be truncated.
93		if replaySize >= 0 {
94			if err := f.Truncate(replaySize); err != nil {
95				f.Close()
96				return nil, err
97			}
98		}
99		if _, err := f.Seek(0, io.SeekEnd); err != nil {
100			f.Close()
101			return nil, err
102		}
103		return &walWriter{f: f, w: bufio.NewWriter(f)}, nil
104	}
105	
106	func (l *walWriter) writeFrame(op byte, key string, value []byte) error {
107		if err := l.encodeFrame(op, key, value); err != nil {
108			return err
109		}
110		if err := l.w.Flush(); err != nil {
111			return err
112		}
113		if err := l.f.Sync(); err != nil {
114			return err
115		}
116		l.syncs++
117		return nil
118	}
119	
120	// encodeFrame buffers one framed record. Used for ordinary appends (followed
121	// by a flush and sync) and while building a replacement log from scratch.
122	func (l *walWriter) encodeFrame(op byte, key string, value []byte) error {
123		hdr := make([]byte, frameHeaderSize)
124		binary.LittleEndian.PutUint32(hdr[0:4], recordMagic)
125		hdr[4] = op
126		binary.LittleEndian.PutUint32(hdr[5:9], uint32(len(key)))
127		binary.LittleEndian.PutUint32(hdr[9:13], uint32(len(value)))
128	
129		h := crc32.NewIEEE()
130		h.Write(hdr)
131		if _, err := l.w.Write(hdr); err != nil {
132			return err
133		}
134		if _, err := io.WriteString(l.w, key); err != nil {
135			return err
136		}
137		h.Write([]byte(key))
138		if len(value) > 0 {
139			if _, err := l.w.Write(value); err != nil {
140				return err
141			}
142			h.Write(value)
143		}
144		var crcb [crcSize]byte
145		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
146		_, err := l.w.Write(crcb[:])
147		return err
148	}
149	
150	// encodeFrameSeq buffers a Seq record: seq's 8 bytes followed by value in
151	// the value area.
152	func (l *walWriter) encodeFrameSeq(op byte, key string, seq uint64, value []byte) error {
153		hdr := make([]byte, frameHeaderSize)
154		binary.LittleEndian.PutUint32(hdr[0:4], recordMagic)
155		hdr[4] = op
156		binary.LittleEndian.PutUint32(hdr[5:9], uint32(len(key)))
157		binary.LittleEndian.PutUint32(hdr[9:13], seqSize+uint32(len(value)))
158	
159		h := crc32.NewIEEE()
160		h.Write(hdr)
161		if _, err := l.w.Write(hdr); err != nil {
162			return err
163		}
164		if _, err := io.WriteString(l.w, key); err != nil {
165			return err
166		}
167		h.Write([]byte(key))
168		var seqb [seqSize]byte
169		binary.LittleEndian.PutUint64(seqb[:], seq)
170		if _, err := l.w.Write(seqb[:]); err != nil {
171			return err
172		}
173		h.Write(seqb[:])
174		if len(value) > 0 {
175			if _, err := l.w.Write(value); err != nil {
176				return err
177			}
178			h.Write(value)
179		}
180		var crcb [crcSize]byte
181		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
182		_, err := l.w.Write(crcb[:])
183		return err
184	}
185	
186	// appendPut writes and durably commits one value record tagged with seq.
187	func (l *walWriter) appendPut(key string, value []byte, seq uint64) error {
188		if len(key) > maxRecord || seqSize+len(value) > maxRecord {
189			return fmt.Errorf("snapshot: record too large")
190		}
191		if err := l.encodeFrameSeq(opPutSeq, key, seq, value); err != nil {
192			return err
193		}
194		if err := l.w.Flush(); err != nil {
195			return err
196		}
197		if err := l.f.Sync(); err != nil {
198			return err
199		}
200		l.syncs++
201		return nil
202	}
203	
204	// appendDelete writes and durably commits one tombstone tagged with seq.
205	func (l *walWriter) appendDelete(key string, seq uint64) error {
206		if len(key) > maxRecord {
207			return fmt.Errorf("snapshot: record too large")
208		}
209		if err := l.encodeFrameSeq(opDeleteSeq, key, seq, nil); err != nil {
210			return err
211		}
212		if err := l.w.Flush(); err != nil {
213			return err
214		}
215		if err := l.f.Sync(); err != nil {
216			return err
217		}
218		l.syncs++
219		return nil
220	}
221	
222	// appendMeta durably records the cumulative snapshot count.
223	func (l *walWriter) appendMeta(snapshotCount uint64) error {
224		var v [metaValueSize]byte
225		binary.LittleEndian.PutUint64(v[:], snapshotCount)
226		return l.writeFrame(opMeta, "", v[:])
227	}
228	
229	// encodeBatch buffers one batch framed by begin/end markers, without
230	// flushing or syncing. Every change is a Seq record carrying its own commit
231	// sequence; end's value holds the inner-frame count. Several batches encoded
232	// back to back can be forced together with one flushSync, which is how
233	// concurrent commits share a single disk sync (group commit) while each
234	// batch stays a self-contained, independently recoverable framed commit.
235	func (l *walWriter) encodeBatch(changes []batchChange) error {
236		var endVal [metaValueSize]byte
237		binary.LittleEndian.PutUint64(endVal[:], uint64(len(changes)))
238		if err := l.encodeFrame(opBatchBegin, "", nil); err != nil {
239			return err
240		}
241		for i := range changes {
242			c := &changes[i]
243			var encErr error
244			if c.delete {
245				encErr = l.encodeFrameSeq(opDeleteSeq, c.key, c.seq, nil)
246			} else {
247				encErr = l.encodeFrameSeq(opPutSeq, c.key, c.seq, c.value)
248			}
249			if encErr != nil {
250				return encErr
251			}
252		}
253		return l.encodeFrame(opBatchEnd, "", endVal[:])
254	}
255	
256	// flushSync forces everything buffered so far to stable storage with one
257	// flush and one fsync.
258	func (l *walWriter) flushSync() error {
259		if err := l.w.Flush(); err != nil {
260			return err
261		}
262		if err := l.f.Sync(); err != nil {
263			return err
264		}
265		l.syncs++
266		return nil
267	}
268	
269	// position returns the current write offset (logical end of the log). It is
270	// only meaningful when no frames are buffered, as at the start of a group.
271	func (l *walWriter) position() (int64, error) {
272		return l.f.Seek(0, io.SeekEnd)
273	}
274	
275	// truncateTo rewinds the log to off, dropping anything a failed group
276	// buffered or auto-flushed past it, and re-arms the buffered writer.
277	func (l *walWriter) truncateTo(off int64) error {
278		l.w.Reset(l.f)
279		if err := l.f.Truncate(off); err != nil {
280			return err
281		}
282		_, err := l.f.Seek(off, io.SeekStart)
283		return err
284	}
285	
286	// appendBatch durably commits one standalone batch: encode and force with a
287	// single sync. Group leaders use encodeBatch plus flushSync directly so one
288	// sync can cover multiple batches.
289	func (l *walWriter) appendBatch(changes []batchChange) error {
290		if err := l.encodeBatch(changes); err != nil {
291			return err
292		}
293		return l.flushSync()
294	}
295	
296	func (l *walWriter) close() error { return l.f.Close() }
297	
298	// syncDirectory forces a directory entry change (such as a rename) to stable
299	// storage.
300	func syncDirectory(dir string) error {
301		d, err := os.Open(dir)
302		if err != nil {
303			return err
304		}
305		defer d.Close()
306		return d.Sync()
307	}
308	
309	// removeStaleCompact deletes a replacement log left behind by a compaction
310	// that crashed before its atomic rename. Its absence is not an error.
311	func removeStaleCompact(dir string) error {
312		err := os.Remove(dir + string(os.PathSeparator) + compactTmpName)
313		if err != nil && !errors.Is(err, os.ErrNotExist) {
314			return err
315		}
316		return nil
317	}
318	
319	// batchChange is one effective change in a batch commit.
320	type batchChange struct {
321		key    string
322		value  []byte // put payload; ignored when delete is true
323		seq    uint64
324		delete bool
325	}
326	
327	// buildCompactWAL writes the complete replacement log to compactTmpName and
328	// durably closes it, without touching wal.log or the live writer. It builds
329	// the complete replacement in compactTmpName and forces it to stable
330	// storage, so a crash at any point leaves either the old log untouched or a
331	// fully built temp that open-time cleanup discards.
332	func buildCompactWAL(dir string, histories []keyHistory, snapshotCount uint64) error {
333		if err := removeStaleCompact(dir); err != nil {
334			return err
335		}
336	
337		path := dir + string(os.PathSeparator)
338		tmp, err := os.OpenFile(path+compactTmpName, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
339		if err != nil {
340			return err
341		}
342		fail := func(err error) error {
343			tmp.Close()
344			os.Remove(path + compactTmpName)
345			return err
346		}
347		l := &walWriter{f: tmp, w: bufio.NewWriter(tmp)}
348		for i := range histories {
349			// Each key's retained versions are oldest-to-newest; replay prepends
350			// them in this order, so the last one becomes the head and every
351			// older one remains reachable down its chain. Frames are only
352			// buffered here; one flush plus one sync below commits the whole
353			// replacement atomically.
354			for _, ver := range histories[i].versions {
355				if ver.present {
356					if err := l.encodeFrameSeq(opPutSeq, histories[i].key, ver.seq, ver.value); err != nil {
357						return fail(err)
358					}
359				} else {
360					if err := l.encodeFrameSeq(opDeleteSeq, histories[i].key, ver.seq, nil); err != nil {
361						return fail(err)
362					}
363				}
364			}
365		}
366		// A zero count needs no record: replay of an absent meta yields 0. This
367		// keeps a trivially empty log empty rather than growing it.
368		if snapshotCount > 0 {
369			var v [metaValueSize]byte
370			binary.LittleEndian.PutUint64(v[:], snapshotCount)
371			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
372				return fail(err)
373			}
374		}
375		if err := l.w.Flush(); err != nil {
376			return fail(err)
377		}
378		if err := tmp.Sync(); err != nil {
379			return fail(err)
380		}
381		if err := tmp.Close(); err != nil {
382			os.Remove(path + compactTmpName)
383			return err
384		}
385		return nil
386	}
387	
388	// installCompactWAL atomically puts a previously built replacement log in
389	// place. The live writer must already have been closed by the caller:
390	// renaming over wal.log while a writer still holds it open fails on native
391	// filesystems that refuse a rename onto an open file, so releasing the old
392	// file first is what makes the swap succeed everywhere.
393	//
394	// renamed reports whether the rename landed. A crash between rename and the
395	// directory sync is still safe: on reopen wal.log is either the old or the
396	// complete new log, never a half-written file. When the rename fails the old
397	// log is intact and is reopened; the returned writer then points at it. When
398	// the rename landed but a writer cannot be opened on the new log, a nil
399	// writer is returned and the caller must treat the store as failed.
400	func installCompactWAL(dir string) (w *walWriter, renamed bool, err error) {
401		path := dir + string(os.PathSeparator)
402		if rerr := os.Rename(path+compactTmpName, path+walName); rerr != nil {
403			// The old log never moved; drop the staged temp so the directory is
404			// left with no intermediate state, then reopen the old log so
405			// committing can continue without needing a second compaction.
406			os.Remove(path + compactTmpName)
407			old, openErr := openWALWriter(dir, -1)
408			if openErr != nil {
409				return nil, false, errors.Join(rerr, openErr)
410			}
411			return old, false, rerr
412		}
413		// Make the rename durable; otherwise a crash could expose the old log
414		// even though the new one was fully written. The rename itself has
415		// already landed either way, so open and return the new writer so the
416		// caller adopts the now-linked file despite reporting the error.
417		syncErr := syncDirectory(dir)
418		next, openErr := openWALWriter(dir, -1)
419		if openErr != nil {
420			return nil, true, errors.Join(syncErr, openErr)
421		}
422		return next, true, syncErr
423	}
424	
425	// nodeVer is one retained version of a key.
426	type nodeVer struct {
427		seq     uint64
428		present bool // false marks a delete
429		value   []byte
430	}
431	
432	// keyHistory is the retained oldest-to-newest version chain for one key in a
433	// compacted log.
434	type keyHistory struct {
435		key      string
436		versions []nodeVer
437	}
438	
439	// replayWAL applies every complete, intact record in commit order. kv
440	// records go to fn with their commit sequence (0 for legacy records that
441	// predate sequence numbers); meta records update snapshotCount. It returns
442	// the number of bytes occupied by the valid prefix; anything after it is a
443	// torn or corrupt tail discarded on the next open.
444	//
445	// Framed batches are applied atomically: their inner records are buffered
446	// until the intact end marker and only then handed to fn in list order. A
447	// torn or corrupt frame anywhere between begin and end (including a missing
448	// or count-mismatched end marker) makes the valid prefix end before the
449	// begin marker, so the whole batch disappears on reopen and no half-batch
450	// ever reaches the in-memory state.
451	func replayWAL(dir string, fn func(op byte, key string, value []byte, seq uint64)) (int64, uint64, error) {
452		f, err := os.Open(dir + string(os.PathSeparator) + walName)
453		if err != nil {
454			if errors.Is(err, os.ErrNotExist) {
455				return 0, 0, nil
456			}
457			return 0, 0, err
458		}
459		defer f.Close()
460	
461		r := bufio.NewReader(f)
462		var offset int64
463		var snapshotCount uint64
464		hdr := make([]byte, frameHeaderSize)
465	
466		// Batch framing state.
467		inBatch := false
468		batchStart := int64(0) // offset of the batch's begin frame
469		var pending []replayedFrame
470	
471		// validPrefix reports where the file must be truncated to. A bad frame
472		// inside a batch invalidates from the batch's begin marker; outside a
473		// batch it invalidates only from that frame.
474		discard := func(at int64) (int64, uint64, error) {
475			if inBatch {
476				return batchStart, snapshotCount, nil
477			}
478			return at, snapshotCount, nil
479		}
480	
481		for {
482			start := offset
483			if _, err := io.ReadFull(r, hdr); err != nil {
484				if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
485					return discard(start) // absent/torn tail: valid prefix ends here
486				}
487				return 0, 0, err
488			}
489			offset += frameHeaderSize
490	
491			magic := binary.LittleEndian.Uint32(hdr[0:4])
492			op := hdr[4]
493			keyLen := binary.LittleEndian.Uint32(hdr[5:9])
494			valLen := binary.LittleEndian.Uint32(hdr[9:13])
495			if magic != recordMagic ||
496				(op != opPut && op != opDelete && op != opMeta &&
497					op != opPutSeq && op != opDeleteSeq &&
498					op != opBatchBegin && op != opBatchEnd) ||
499				keyLen > maxRecord || valLen > maxRecord ||
500				(op == opDelete && valLen != 0) ||
501				(op == opPutSeq && valLen < seqSize) ||
502				(op == opDeleteSeq && valLen != seqSize) ||
503				(op == opMeta && (keyLen != 0 || valLen != metaValueSize)) ||
504				(op == opBatchBegin && (keyLen != 0 || valLen != 0)) ||
505				(op == opBatchEnd && (keyLen != 0 || valLen != metaValueSize)) {
506				return discard(start) // corrupt frame: valid prefix ends here
507			}
508	
509			body := make([]byte, int(keyLen)+int(valLen))
510			if _, err := io.ReadFull(r, body); err != nil {
511				return discard(start)
512			}
513			offset += int64(len(body))
514	
515			var crcb [crcSize]byte
516			if _, err := io.ReadFull(r, crcb[:]); err != nil {
517				return discard(start)
518			}
519			offset += crcSize
520	
521			h := crc32.NewIEEE()
522			h.Write(hdr)
523			h.Write(body)
524			if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
525				return discard(start)
526			}
527	
528			switch op {
529			case opBatchBegin:
530				if inBatch {
531					return batchStart, snapshotCount, nil // nested begin: corrupt batch
532				}
533				inBatch = true
534				batchStart = start
535				pending = pending[:0]
536			case opBatchEnd:
537				count := binary.LittleEndian.Uint64(body)
538				if !inBatch || count != uint64(len(pending)) {
539					// Stray end, or an end whose count does not match the
540					// buffered inner frames: the framed commit is not intact.
541					return discard(start)
542				}
543				for _, fr := range pending {
544					fn(fr.op, fr.key, fr.value, fr.seq)
545				}
546				pending = pending[:0]
547				inBatch = false
548			case opPut:
549				if inBatch {
550					return batchStart, snapshotCount, nil // only Seq frames may batch
551				}
552				fn(opPut, string(body[:keyLen]), body[keyLen:], 0)
553			case opDelete:
554				if inBatch {
555					return batchStart, snapshotCount, nil
556				}
557				fn(opDelete, string(body[:keyLen]), nil, 0)
558			case opPutSeq:
559				key := string(body[:keyLen])
560				seq := binary.LittleEndian.Uint64(body[keyLen : keyLen+seqSize])
561				value := body[keyLen+seqSize:]
562				if inBatch {
563					pending = append(pending, replayedFrame{opPutSeq, key, value, seq})
564				} else {
565					fn(opPutSeq, key, value, seq)
566				}
567			case opDeleteSeq:
568				key := string(body[:keyLen])
569				seq := binary.LittleEndian.Uint64(body[keyLen : keyLen+seqSize])
570				if inBatch {
571					pending = append(pending, replayedFrame{opDeleteSeq, key, nil, seq})
572				} else {
573					fn(opDeleteSeq, key, nil, seq)
574				}
575			case opMeta:
576				if inBatch {
577					return batchStart, snapshotCount, nil // meta may not ride inside a batch
578				}
579				snapshotCount = binary.LittleEndian.Uint64(body)
580			}
581		}
582	}
583	
584	// replayedFrame is one inner batch frame held during replay until its batch's
585	// end marker proves the commit is complete.
586	type replayedFrame struct {
587		op    byte
588		key   string
589		value []byte
590		seq   uint64
591	}
592

